import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { IssueId } from "@/types/common";
import type { IssueRollup, IssueStatus } from "@/types/issue";

/** Raised when a parent assignment would loop the tree or nest it too deeply. */
export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: "cycle" | "too_deep",
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or one of its sub-issues.`
        : `Issue ${issueId} would nest sub-issues too deeply.`,
    );
    this.name = "IssueHierarchyError";
  }
}

/** The slice of an issue row the tree arithmetic needs. */
export interface IssueNode {
  readonly id: IssueId;
  readonly parentId: IssueId | null;
  readonly status: IssueStatus;
  readonly archivedAt: string | null;
}

export type IssueNodeIndex = ReadonlyMap<IssueId, IssueNode>;

export function indexNodes(nodes: readonly IssueNode[]): IssueNodeIndex {
  return new Map(nodes.map((node) => [node.id, node]));
}

function childrenOf(nodes: readonly IssueNode[]): Map<IssueId, IssueNode[]> {
  const children = new Map<IssueId, IssueNode[]>();
  for (const node of nodes) {
    if (node.parentId === null) continue;
    const bucket = children.get(node.parentId) ?? [];
    bucket.push(node);
    children.set(node.parentId, bucket);
  }
  return children;
}

/** Every issue below `rootId` at any depth (archived ones included). */
export function descendantsOf(
  nodes: readonly IssueNode[],
  rootId: IssueId,
): readonly IssueNode[] {
  const children = childrenOf(nodes);
  const seen = new Set<IssueId>([rootId]);
  const found: IssueNode[] = [];
  const queue: IssueId[] = [rootId];

  for (let at = 0; at < queue.length; at += 1) {
    for (const child of children.get(queue[at] as IssueId) ?? []) {
      if (seen.has(child.id)) continue;
      seen.add(child.id);
      found.push(child);
      queue.push(child.id);
    }
  }
  return found;
}

/** Levels between `rootId` and its deepest descendant; 0 for a leaf. */
export function subtreeHeight(
  nodes: readonly IssueNode[],
  rootId: IssueId,
): number {
  const children = childrenOf(nodes);
  const seen = new Set<IssueId>([rootId]);
  let level: readonly IssueId[] = [rootId];
  let height = 0;

  for (;;) {
    const next: IssueId[] = [];
    for (const id of level) {
      for (const child of children.get(id) ?? []) {
        if (seen.has(child.id)) continue;
        seen.add(child.id);
        next.push(child.id);
      }
    }
    if (next.length === 0) return height;
    height += 1;
    level = next;
  }
}

/** Level of an issue: 0 for a root, one more per ancestor. */
export function levelOf(index: IssueNodeIndex, id: IssueId): number {
  const seen = new Set<IssueId>([id]);
  let level = 0;
  let at = index.get(id)?.parentId ?? null;
  while (at !== null && !seen.has(at)) {
    seen.add(at);
    level += 1;
    at = index.get(at)?.parentId ?? null;
  }
  return level;
}

export function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/** Counts the live issues in `below`. */
export function rollupOf(below: readonly IssueNode[]): IssueRollup {
  let open = 0;
  let closed = 0;
  for (const node of below) {
    if (node.archivedAt !== null) continue;
    if (isClosedStatus(node.status)) closed += 1;
    else open += 1;
  }
  return { total: open + closed, open, closed };
}
