export async function listProjectIssueNodes(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly IssueNode[]> {
  const rows = getDb()
    .select({
      id: issues.id,
      parentId: issues.parentId,
      status: issues.status,
      archivedAt: issues.archivedAt,
    })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .all();

  return rows.map((row) => ({
    id: row.id as IssueId,
    parentId: row.parentId === null ? null : (row.parentId as IssueId),
    status: row.status,
    archivedAt: row.archivedAt,
  }));
}

/** Live direct children of one issue, oldest first. */
export async function listSubIssues(
  orgId: OrgId,
  parentId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.parentId, parentId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(asc(issues.createdAt), asc(issues.number), asc(issues.id))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

export async function setIssueParent(
  orgId: OrgId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<void> {
  const row = getDb()
    .update(issues)
    .set({ parentId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning({ id: issues.id })
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
}

/** Archives the still-live rows among `issueIds`; returns the ids it archived. */
export async function archiveIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly IssueId[]> {
  const archived: IssueId[] = [];
  const CHUNK = 500;

  for (let at = 0; at < issueIds.length; at += CHUNK) {
    const rows = getDb()
      .update(issues)
      .set(archivePatch())
      .where(
        and(
          ...compact(
            orgPredicate(issues.orgId, orgId),
            livePredicate(issues.archivedAt, {}),
            inArray(issues.id, issueIds.slice(at, at + CHUNK)),
          ),
        ),
      )
      .returning({ id: issues.id })
      .all();
    archived.push(...rows.map((row) => row.id as IssueId));
  }
  return archived;
}
