/**
 * Places an issue under another parent of its project, or back at the root.
 * The sub-issues below it travel along, so the depth limit is judged by where
 * its deepest descendant would land.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  if (input.parentId !== null) {
    await assertValidParent(
      input.orgId,
      issue.projectId,
      input.parentId,
      issue.id,
    );
  }

  if (issue.parentId === input.parentId) return issue;

  await issueRepo.setIssueParent(input.orgId, issue.id, input.parentId);
  const after = requireFound(
    await issueRepo.findIssueById(input.orgId, issue.id),
    "Issue",
    issue.id,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return issueRepo.listSubIssues(orgId, issue.id);
}

export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const nodes = await issueRepo.listProjectIssueNodes(orgId, issue.projectId);
  return rollupOf(descendantsOf(nodes, issue.id));
}

/**
 * Gate shared by creation and moves: the parent must be a live issue of the
 * same project, must not sit at or below the moved issue (`movingId`; null for
 * a brand-new issue) and must leave every moved level within the depth limit.
 */
async function assertValidParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
  movingId: IssueId | null,
): Promise<void> {
  const parent = requireFound(
    await issueRepo.findIssueById(orgId, parentId),
    "Issue",
    parentId,
  );
  if (parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  assertNotArchived("Issue", parent.id, parent);

  const nodes = await issueRepo.listProjectIssueNodes(orgId, projectId);

  if (movingId !== null) {
    if (
      parent.id === movingId ||
      descendantsOf(nodes, movingId).some((node) => node.id === parent.id)
    ) {
      throw new IssueHierarchyError(movingId, "cycle");
    }
  }

  const landing =
    levelOf(indexNodes(nodes), parent.id) +
    1 +
    (movingId === null ? 0 : subtreeHeight(nodes, movingId));
  if (landing > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(movingId ?? parentId, "too_deep");
  }
}

/**
 * Tells the direct parent's assignee when a sub-issue that stopped being open
 * leaves the parent with no open issue anywhere below it. The fan-out applies
 * preferences and never notifies the person who made the change.
 */
async function announceSubIssuesCompleted(
  actor: Actor,
  closed: Issue,
): Promise<void> {
  if (closed.parentId === null) return;

  const parent = await issueRepo.findIssueById(closed.orgId, closed.parentId);
  if (!parent || parent.archivedAt !== null || parent.assigneeId === null) {
    return;
  }

  const nodes = await issueRepo.listProjectIssueNodes(
    closed.orgId,
    parent.projectId,
  );
  if (rollupOf(descendantsOf(nodes, parent.id)).open > 0) return;

  await notify(closed.orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "All sub-issues are completed",
    body: `Every sub-issue of issue ${parent.id} is closed`,
    href: `/issues/${parent.id}`,
    actorId: actor.userId,
  });
}
